def poly(x, k):
    from itertools import combinations_with_replacement as cw
    return np.column_stack([np.prod(x[:, j], axis=1) for j in cw(range(x.shape[1]), k)])

def act(a, kind):
    if kind == 'sin':
        return np.sin(a)
    if kind == 'tanh':
        return np.tanh(a)
    if kind == 'soft':
        return a / (1 + abs(a))
    if kind == 'cos':
        return np.cos(a)
    if kind == 'recip':
        return 1 / (1 + a * a)
    return a * np.exp(-a * a / 2)

def ridge_rat(X, U, Y, V, W, kind, reg=0.015):
    from scipy.optimize import least_squares
    F = design(X, 2)
    G = design(U, 2)
    d = V.shape[1]
    cen = V.mean(0)
    V = V - cen
    W = W - cen

    def den(A, p):
        if kind == 'rad':
            return 1 + np.exp(p[0]) * np.sum(A * A, axis=1)
        if kind == 'diag':
            return 1 + A * A @ np.exp(p)
        return 1 + (A @ p[1:] + p[0]) ** 2

    def calc(p, ret=False):
        D = F / den(V, p)[:, None]
        a = np.linalg.lstsq(np.r_[D, np.eye(F.shape[1]) * reg], np.r_[Y, np.zeros(F.shape[1])], rcond=None)[0]
        return G @ a / den(W, p) if ret else np.r_[D @ a - Y, reg * a, 0.012 * p]
    if kind == 'rad':
        starts = [[-1.8], [-0.6]]
    elif kind == 'diag':
        starts = [np.full(d, -2), np.full(d, -0.5)]
    else:
        starts = [np.r_[0, p] for p in np.eye(d) * 0.35] + [np.full(d + 1, 0.15)]
    b = min((least_squares(calc, p, max_nfev=100) for p in starts), key=lambda o: o.cost)
    return calc(b.x, True)
